{
  "registry_schema_version": 1,
  "query": {
    "selector": "catalog",
    "value": null,
    "include": "summary"
  },
  "capability": {
    "status": "implemented"
  },
  "next_tools": [
    "solve_rule_spec",
    "solve_rules"
  ],
  "families": [
    {
      "id": "accessibility",
      "family_version": 1,
      "summary": "WCAG-backed geometry and contrast rules over normalized UI facts.",
      "profiles": [
        "wcag_geometry_color"
      ]
    },
    {
      "id": "configuration",
      "family_version": 1,
      "summary": "Finite component selection, attribute compatibility, and ranked-version constraints.",
      "profiles": [
        "finite_compatibility"
      ]
    },
    {
      "id": "data_integrity",
      "family_version": 1,
      "summary": "Finite relational snapshot verification and bounded synthesis for strict identity, reference, cardinality, value, aggregate, tuple, and temporal integrity rules.",
      "profiles": [
        "finite_relational_snapshot"
      ]
    },
    {
      "id": "design",
      "family_version": 1,
      "summary": "Mathematically enforceable UI layout and graphic-design rules.",
      "profiles": [
        "geometric_integrity",
        "layout_capacity"
      ]
    },
    {
      "id": "policy",
      "family_version": 1,
      "summary": "Finite RBAC reachability, hierarchy, and separation-of-duty rules.",
      "profiles": [
        "nist_rbac"
      ]
    },
    {
      "id": "resource",
      "family_version": 1,
      "summary": "Resource demand, capacity, quota, and topology placement constraints.",
      "profiles": [
        "capacity",
        "topology_placement"
      ]
    },
    {
      "id": "scheduling",
      "family_version": 1,
      "summary": "Discrete finite-horizon, non-preemptive job assignment, placement, capacity, precedence, and makespan rules.",
      "profiles": [
        "finite_horizon"
      ]
    },
    {
      "id": "workflow",
      "family_version": 1,
      "summary": "Finite bounded-trace workflow verification and bounded witness or counterexample search over caller-normalized states, events, and enabled transitions.",
      "profiles": [
        "bounded_trace"
      ]
    }
  ]
}
